/**
 * THE CELLAR PLATE
 *
 * A painted room, supplied rather than generated — empty shelves and clear floor,
 * so every jar and cask you see down there is a real batch rather than scenery.
 * That is the whole reason for a second version of this picture: with painted
 * vessels on the shelves you could not tell which ones were yours.
 *
 * It lives here as a data URI and not as a file in `public/` for one reason: the
 * game ships as a single self-contained page and that page's CSP blocks external
 * images, so `<img src="/art/cellar.jpg">` works on the dev server and shows
 * nothing at all once published — the worst kind of bug, invisible where you test.
 *
 * Recompressed from the original to 214 kB at the size it is drawn.
 * Source kept at art/cellar-source.jpg.
 */
export const CELLAR_PLATE = "data:image/jpeg;base64,";
